commands.linux:
# Standalone example: this host's containers, as text.
command -v docker >/dev/null || { echo 'docker is not installed'; exit 0; }
docker ps --all --format '{{.Names}} {{.Image}} {{.State}}'

commands.darwin:
# Standalone example: this host's containers, as text.
command -v docker >/dev/null || { echo 'docker is not installed'; exit 0; }
docker ps --all --format '{{.Names}} {{.Image}} {{.State}}'

commands.windows:
# Standalone example: this host's containers, as text. The built-in sensor reports nothing on Windows.
if (-not (Get-Command docker -ErrorAction SilentlyContinue)) { 'docker is not installed'; exit 0 }
docker ps --all --format '{{.Names}} {{.Image}} {{.State}}'
